/*
 * m3vcpu_webgpu_kernels.h - WGSL twins compiled into the webgpu backend (table generated by
 * m3vcpu_webgpu_embed.cmake from kernels/<name>.wgsl).
 *
 * The core's built-in bundle carries M3K_OPENCL_C + M3K_CPU_SYMBOL blobs only. When kernel_load
 * gets no M3K_WGSL blob, the backend serves the twin registered for the entry name, but only if
 * the offered M3K_OPENCL_C blob is byte-identical (same sha256) to the source the twin was built
 * and admitted against. Any other OpenCL C source is refused with M3VCPU_E_NO_KERNEL_FORMAT.
 */
#ifndef M3VCPU_WEBGPU_KERNELS_H
#define M3VCPU_WEBGPU_KERNELS_H

#include <stddef.h>
#include <stdint.h>

typedef struct m3_wg_twin {
    const char *entry;           /* kernel entry point (WGSL @compute function name)          */
    uint32_t nargs;              /* storage-buffer bindings @group(0) @binding(0..nargs-1)      */
    const uint8_t *wgsl;         /* UTF-8 WGSL source                                         */
    size_t size;
    uint8_t wgsl_sha256[32];     /* content address of wgsl[0, size); re-checked at load      */
    uint8_t paired_sha256[32];   /* sha256 of the M3K_OPENCL_C blob this twin restates         */
} m3_wg_twin;

extern const m3_wg_twin m3_wg_twins[];
extern const size_t m3_wg_twin_count;

#endif /* M3VCPU_WEBGPU_KERNELS_H */
